CREATE OR REPLACE PROCEDURE sp(para_Club_ID_1 INTEGER, para_Score VARCHAR2, Club_ID_2 INTEGER, para_Apps REAL, para_Position VARCHAR2, Tries REAL) AS
    v_action_code VARCHAR2(4000);
    v_club_id_2 INTEGER;
    v_tries REAL;
BEGIN
    v_club_id_2 := Club_ID_2;
    v_tries := Tries;

    IF para_Club_ID_1 < 10 THEN
        v_action_code := 'A10';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps;
    ELSIF para_Club_ID_1 < 20 THEN
        v_action_code := 'A20';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps + 10;
    ELSIF para_Club_ID_1 < 30 THEN
        v_action_code := 'A30';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps + 20;
    ELSIF para_Club_ID_1 < 40 THEN
        v_action_code := 'A40';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps + 30;
    ELSIF para_Club_ID_1 < 50 THEN
        v_action_code := 'A50';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps + 40;
    ELSIF para_Club_ID_1 < 60 THEN
    -- <<< region omitted from the export >>>
    ELSIF para_Club_ID_1 < 70 THEN
        v_action_code := 'A70';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps + 60;
    ELSIF para_Club_ID_1 < 80 THEN
        v_action_code := 'A80';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" < para_Apps + 70;
    ELSE
        v_action_code := 'A_DEFAULT';
        UPDATE "competition_result" SET "Score" = v_action_code;
        DELETE FROM "player" WHERE "Apps" > para_Apps;
    END IF;

    UPDATE "competition_result" SET "Score" = para_Score WHERE "Club_ID_1" = para_Club_ID_1;
    UPDATE "player" SET "Position" = para_Position WHERE "Apps" = para_Apps;
    DELETE FROM "competition_result" WHERE "Score" IS NULL;
    DELETE FROM "player" WHERE "Position" IS NULL;
    DELETE FROM "competition_result" WHERE "Club_ID_2" = 0;
    DELETE FROM "player" WHERE "Tries" = 0;
    DELETE FROM "player" WHERE "Tries" > v_tries;

    IF v_club_id_2 > 0 THEN
        DELETE FROM "competition_result" WHERE "Club_ID_2" = v_club_id_2;
    END IF;
END;

